    {
        await mgmt.SetDeviceConfigAsync(new DeviceConfig { AutoEjectTimeout = original.AutoEjectTimeout });
        var restored = await mgmt.GetDeviceInfoAsync();
        Assert.Equal(original.AutoEjectTimeout, restored.AutoEjectTimeout);
    }
}

